// Wizard Idle v2 - the travel graph at run time (docs/TRAVEL.md). The graph itself is generated by
// tools/travel_graph.py (src/data/travelGraph.js); here is Dijkstra over it (about 80 nodes: instant).
//
//   travelCost(a, b)   cheapest cost of walking between two spots, in map pixels
//   route(a, b)        the cheapest path as a list of {layer, x, y} points
//   destinations(stage), moves(stage)   the adapter: the same lists the old strings gave
//
// A spot is a stage name ("la_Pradera2") or a point {layer, x, y} in map pixels (the 250 px maps).
// Dynamic scenes: dynamicScenes(cost) turns a walking cost into how many intermediate scenes a leg needs (the longer, the more).
// The graph itself still knows nothing else about scenes.

import { travelGraph as g } from './data/travelGraph.js';
import { places } from './data/zones.js';
import { config } from './config.js';
import { travelOverrides } from './data/travelOverrides.js';

// Manual verdicts of a pair of stages (see data/travel.json); the dev tools edit this object.
const overrides = { ...travelOverrides };
const pairKey = (a, b) => a < b ? `${a}|${b}` : `${b}|${a}`;
const verdict = (a, b) => overrides[pairKey(a, b)] || '';

const SIZE = 250;
const byName = { ...g.anchors };     // stage names and the waypoints' names (bridges, pier, cave mouths, stairs) -> node
g.nodes.forEach((n, i) => { if (n[4]) byName[n[4]] = i; });
const cache = new Map();            // source node -> {dist, prev}; cleared when the graph changes
let adj = [];

// The adjacency lists: the manual verdicts only (a pair set Accessible gets a cheap edge, Difficult a dear one,
// Impossible none), so a quest route never uses a step that moves() and destinations() would not take. The dev tools call this after changing the verdicts.
function rebuild() {
    const edges = new Map(), t = config.travel;      // only the author's links: the generated edges are walls he could not walk
    for (const [k, v] of Object.entries(overrides)) {
        const [x, y] = k.split('|'), a = byName[x], b = byName[y];
        if (a === undefined || b === undefined || a === b) continue;
        const key = a < b ? `${a},${b}` : `${b},${a}`;
        if (v === 'far') edges.delete(key);
        else if (v === 'move') edges.set(key, t.accessibleCost);
        else edges.set(key, t.difficultMin);
    }
    adj = g.nodes.map(() => []);
    for (const [key, c] of edges) { const [a, b] = key.split(',').map(Number); adj[a].push([b, c]); adj[b].push([a, c]); }
    cache.clear();
}

// The node of a spot; a free point joins the graph at its nearest node of the same layer.
function nodeOf(spot) {
    if (typeof spot === "string") return byName[spot];
    let best = -1, bestD = Infinity;
    g.nodes.forEach(([layer, x, y], i) => {
        const d = Math.hypot(x - spot.x, y - spot.y);
        if (layer === spot.layer && d < bestD) { best = i; bestD = d; }
    });
    return best;
}

function from(src) {
    if (cache.has(src)) return cache.get(src);
    const dist = g.nodes.map(() => Infinity), prev = g.nodes.map(() => -1), done = g.nodes.map(() => false);
    dist[src] = 0;
    for (;;) {                      // a plain scan: with this few nodes a heap buys nothing
        let u = -1;
        for (let i = 0; i < dist.length; i++) if (!done[i] && (u < 0 || dist[i] < dist[u])) u = i;
        if (u < 0 || dist[u] === Infinity) break;
        done[u] = true;
        for (const [v, c] of adj[u]) if (dist[u] + c < dist[v]) { dist[v] = dist[u] + c; prev[v] = u; }
    }
    const r = { dist, prev };
    cache.set(src, r);
    return r;
}

function travelCost(a, b) {
    return from(nodeOf(a)).dist[nodeOf(b)];
}

// The cheapest path as a list of node numbers (g.nodes), the way the dev tools draw it.
function routeIds(a, b) {
    const { prev } = from(nodeOf(a));
    const ids = [];
    for (let n = nodeOf(b); n >= 0; n = prev[n]) ids.unshift(n);
    return ids;
}

// How many dynamic scenes a leg of this cost needs: one for anything short, one more per config.travel.pxPerScene of cost.
function dynamicScenes(cost) {
    return Math.max(1, Math.ceil(cost / config.travel.pxPerScene));
}

function route(a, b) {
    return routeIds(a, b).map((n) => { const [layer, x, y] = g.nodes[n]; return { layer, x, y }; });
}

// The graph IS the author's manual links (Modes > Travel, data/travel.json): Accessible and Difficult
// both lead somewhere, Impossible does not. A stage is anything in `places`; a point that is not a stage
// (a bridge, a cave mouth, the stairs) only passes the trip on to the stages linked to it.
// Stages linked to a stage, directly or through such points, as {stage name: true}.
function linkMap() {
    const nb = {};
    for (const [k, v] of Object.entries(overrides)) {
        if (v === 'far') continue;
        const [a, b] = k.split('|');
        (nb[a] = nb[a] || []).push(b);
        (nb[b] = nb[b] || []).push(a);
    }
    return nb;
}

function linked(stage) {
    const nb = linkMap();
    const found = {}, seen = new Set([stage]), todo = [stage];
    while (todo.length) {
        for (const n of nb[todo.pop()] || []) {
            if (seen.has(n)) continue;
            seen.add(n);
            if (places[n]) found[n] = true; else todo.push(n);     // a stage ends the walk, a connector passes it on
        }
    }
    for (const n of Object.keys(found)) if (verdict(stage, n) === 'far') delete found[n];
    return Object.keys(found);
}

// The connector points (bridges, mouths, stairs) a trip from one stage to another passes, in order; [] when
// the link is direct. The shortest way through the manual links, a stage ending the walk.
function connectorsBetween(a, b) {
    const nb = linkMap(), prev = { [a]: null }, todo = [a];
    while (todo.length) {
        const n = todo.shift();
        if (n === b) break;
        if (n !== a && places[n]) continue;
        for (const m of nb[n] || []) if (!(m in prev)) { prev[m] = n; todo.push(m); }
    }
    const chain = [];
    for (let n = prev[b]; n && n !== a; n = prev[n]) chain.unshift(n);
    return b in prev ? chain : [];
}

// True when a stage reaches a named connector point (the pier) through the manual links, a stage ending the walk.
function reachesPoint(stage, point) {
    const nb = linkMap(), seen = new Set([stage]), todo = [stage];
    while (todo.length) {
        for (const n of nb[todo.pop()] || []) {
            if (n === point) return true;
            if (seen.has(n) || places[n]) continue;
            seen.add(n);
            todo.push(n);
        }
    }
    return false;
}

// Where a named point sits on its map (x in map pixels), or undefined.
function spotX(name) {
    const i = byName[name];
    return i === undefined ? undefined : g.nodes[i][1];
}

// Where a named point sits on its map as fractions of the map and its layer ("ground", "under", "above"), or undefined.
function pointSpot(name) {
    const i = byName[name];
    if (i === undefined) return undefined;
    const [layer, x, y] = g.nodes[i];
    return { layer, x: x / SIZE, y: y / SIZE };
}

// The stages he may go to in another zone, from the manual links; none linked yet: the old typed list.
function destinations(stage) {
    const z = places[stage].zone, list = linked(stage).filter(n => places[n].zone !== z);
    return list.length ? list : oldList(stage, 'destinations');
}

// The stages he may walk to inside his zone, from the manual links; none linked yet: the old typed list.
function moves(stage) {
    const z = places[stage].zone, list = linked(stage).filter(n => places[n].zone === z);
    return list.length ? list : oldList(stage, 'moves');
}

// The typed strings of zones.js (kept for stages not linked yet); a new stage with none borrows its zone's first stage.
function oldList(stage, key) {
    const own = places[stage][key], first = places[`${places[stage].zone}1`][key];
    return (own || first).split(',').filter(Boolean);
}

rebuild();

// The direct links of a spot: [[node, cost], ...], after the manual verdicts (the dev tools draw them).
const neighbors = (spot) => adj[nodeOf(spot)] || [];

export { dynamicScenes, reachesPoint, connectorsBetween, spotX, pointSpot, neighbors, byName, rebuild, travelCost, route, routeIds, destinations, moves, overrides, pairKey, verdict, SIZE };
